option.value:
:root {
    /* Enhanced Color Palette - More professional and catchy */
    --color-primary: #4361ee;
    --color-primary-light: #4895ef;
    --color-primary-dark: #3f37c9;
    --color-accent: #f72585;
    --color-accent-light: #ff5dab;
    --color-accent-dark: #dc136c;
    --color-gradient-1: #4361ee;
    --color-gradient-2: #3a0ca3;
    --color-bg: #f8f9ff;
    --color-bg-card: #ffffff;
    --color-text: #0f172a;
    --color-text-secondary: #334155;
    --color-border: #e2e8f0;
    --color-shadow: rgba(15, 23, 42, 0.05);
    --color-shadow-heavy: rgba(15, 23, 42, 0.12);
    --color-success: #06d6a0;
    --color-error: #ef476f;
    --color-warning: #ffd166;
    --color-overlay: rgba(15, 23, 42, 0.6);

    /* Spacing - Unchanged */
    --space-xs: 0.25rem;
    --space-sm: 0.5rem;
    --space-md: 1rem;
    --space-lg: 1.5rem;
    --space-xl: 2rem;
    --space-xxl: 3rem;

    /* Font Family - Unchanged */
    --font-primary: 'Inter', sans-serif;
    --font-heading: 'Montserrat', sans-serif;

    /* Transitions */
    --transition-fast: 0.2s ease;
    --transition-normal: 0.3s ease;
    --transition-slow: 0.5s ease;

    /* Border Radius - Enhanced for modern look */
    --radius-sm: 6px;
    --radius-md: 8px;
    --radius-lg: 12px;
    --radius-xl: 16px;
    --radius-full: 9999px;
}

/* Dark Theme Colors - Enhanced for better contrast and visual appeal */
[data-theme="dark"] {
    --color-primary: #4cc9f0;
    --color-primary-light: #72efdd;
    --color-primary-dark: #4895ef;
    --color-accent: #f72585;
    --color-accent-light: #ff5dab;
    --color-accent-dark: #b5179e;
    --color-gradient-1: #4cc9f0;
    --color-gradient-2: #7209b7;
    --color-bg: #0f172a;
    --color-bg-card: #1e293b;
    --color-text: #f1f5f9;
    --color-text-secondary: #cbd5e1;
    --color-border: #334155;
    --color-shadow: rgba(0, 0, 0, 0.2);
    --color-shadow-heavy: rgba(0, 0, 0, 0.4);
    --color-success: #06d6a0;
    --color-error: #ef476f;
    --color-warning: #ffd166;
    --color-overlay: rgba(0, 0, 0, 0.75);
}

/* Base Styles - Enhanced with subtle background */
*, *::before, *::after {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html {
    font-size: 16px;
}

body {
    font-family: var(--font-primary);
    background-color: var(--color-bg);
    background-image: radial-gradient(circle at 100% 100%, rgba(99, 102, 241, 0.05) 0%, transparent 50%),
                     radial-gradient(circle at 0% 0%, rgba(99, 102, 241, 0.03) 0%, transparent 40%);
    color: var(--color-text);
    line-height: 1.6;
    transition: background-color var(--transition-normal), color var(--transition-normal);
}

/* Container */
.container {
    max-width: 900px;
    margin: 0 auto;
    padding: var(--space-lg);
}

/* Header - Enhanced with subtle gradient */
header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: var(--space-xl);
    padding-bottom: var(--space-md);
    border-bottom: 1px solid rgba(99, 102, 241, 0.1);
}

h1 {
    font-family: var(--font-heading);
    background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-accent) 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    text-fill-color: transparent;
    font-size: 2.5rem;
    text-align: center;
    letter-spacing: -0.5px;
    position: relative;
}

/* Dark Mode Toggle - Enhanced with better styling */
.theme-toggle-wrapper {
    display: flex;
    align-items: center;
}

#theme-toggle {
    appearance: none;
    outline: none;
    border: none;
    background: none;
    cursor: pointer;
    padding: 0;
}

.theme-toggle-track {
    position: relative;
    display: inline-block;
    width: 52px;
    height: 28px;
    background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-accent) 100%);
    border-radius: var(--radius-full);
    padding: 3px;
    transition: var(--transition-normal);
    box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
}

.theme-toggle-icon {
    position: absolute;
    top: 3px;
    display: flex;
    align-items: center;
    justify-content: center;
    width: 22px;
    height: 22px;
    font-size: 14px;
    border-radius: 50%;
    transition: transform var(--transition-normal);
}

.light-icon {
    left: 3px;
    transform: translateX(0);
}

.dark-icon {
    right: 3px;
    transform: translateX(0);
    opacity: 0.5;
}

[data-theme="dark"] .light-icon {
    opacity: 0.5;
}

[data-theme="dark"] .dark-icon {
    opacity: 1;
}

/* Tabs - Enhanced with better styling and animations */
.tabs {
    display: flex;
    justify-content: center;
    margin-bottom: var(--space-lg);
    position: relative;
    z-index: 1;
}

.tab-btn {
    padding: var(--space-md) var(--space-xl);
    background: var(--color-bg-card);
    border: 1px solid var(--color-border);
    border-bottom: none;
    cursor: pointer;
    font-family: var(--font-primary);
    font-weight: 600;
    font-size: 1rem;
    color: var(--color-text-secondary);
    outline: none;
    transition: all var(--transition-fast);
    box-shadow: 0 -2px 10px var(--color-shadow);
}

.tab-btn:first-child {
    border-radius: var(--radius-md) 0 0 0;
}

.tab-btn:last-child {
    border-radius: 0 var(--radius-md) 0 0;
}

.tab-btn.active {
    background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-primary-dark) 100%);
    color: white;
    border-color: transparent;
    box-shadow: 0 4px 12px rgba(67, 97, 238, 0.3);
}

.tab-btn:hover:not(.active) {
    background: var(--color-bg);
    color: var(--color-primary);
    transform: translateY(-2px);
}

.tab-pane {
    display: none;
    background: var(--color-bg-card);
    padding: var(--space-xl);
    border-radius: var(--radius-lg);
    box-shadow: 0 10px 25px var(--color-shadow), 0 2px 5px var(--color-shadow);
    transition: all var(--transition-normal);
    animation: fadeIn var(--transition-normal);
    border-top: 4px solid var(--color-primary);
}

.tab-pane.active {
    display: block;
    opacity: 1;
    transform: translateY(0);
}

@keyframes fadeIn {
    from { opacity: 0; transform: translateY(10px); }
    to { opacity: 1; transform: translateY(0); }
}

/* QR Generator - Enhanced input and button styling */
.input-group {
    display: flex;
    margin-bottom: var(--space-lg);
    box-shadow: 0 4px 10px var(--color-shadow);
    border-radius: var(--radius-md);
}

#qr-text {
    flex: 1;
    padding: var(--space-md) var(--space-lg);
    border: 2px solid var(--color-border);
    border-radius: var(--radius-md) 0 0 var(--radius-md);
    font-size: 1rem;
    font-family: var(--font-primary);
    color: var(--color-text);
    background-color: var(--color-bg-card);
    outline: none;
    transition: border-color var(--transition-fast), box-shadow var(--transition-fast);
}

#qr-text:focus {
    border-color: var(--color-primary);
    box-shadow: 0 0 0 3px rgba(67, 97, 238, 0.2);
}

#generate-btn {
    padding: var(--space-md) var(--space-lg);
    background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-primary-dark) 100%);
    color: white;
    border: none;
    border-radius: 0 var(--radius-md) var(--radius-md) 0;
    cursor: pointer;
    font-size: 1rem;
    font-weight: 600;
    transition: all var(--transition-fast);
}

#generate-btn:hover {
    background: linear-gradient(135deg, var(--color-primary-light) 0%, var(--color-primary) 100%);
    transform: translateY(-2px);
    box-shadow: 0 4px 12px rgba(67, 97, 238, 0.3);
}

#generate-btn:active {
    transform: translateY(0);
    box-shadow: 0 2px 6px rgba(67, 97, 238, 0.3);
}

.qr-result {
    display: flex;
    flex-direction: column;
    align-items: center;
    margin-top: var(--space-xl);
}

#qr-canvas {
    background: white;
    padding: var(--space-md);
    border-radius: var(--radius-md);
    box-shadow: 0 10px 25px var(--color-shadow), 0 2px 5px var(--color-shadow);
    margin-bottom: var(--space-lg);
    max-width: 100%;
    transition: transform var(--transition-normal), box-shadow var(--transition-normal);
}

#qr-canvas:hover {
    transform: scale(1.02) translateY(-5px);
    box-shadow: 0 15px 35px var(--color-shadow-heavy);
}

#download-btn {
    padding: var(--space-md) var(--space-xl);
    background: linear-gradient(135deg, var(--color-success) 0%, #04aa82 100%);
    color: white;
    border: none;
    border-radius: var(--radius-full);
    cursor: pointer;
    font-size: 0.95rem;
    font-weight: 600;
    display: none; /* Initially hidden */
    transition: all var(--transition-fast);
    box-shadow: 0 4px 10px rgba(6, 214, 160, 0.3);
}

#download-btn:hover {
    box-shadow: 0 6px 15px rgba(6, 214, 160, 0.4);
    filter: brightness(105%);
    transform: translateY(-2px);
}

#download-btn:active {
    transform: translateY(0);
    box-shadow: 0 2px 6px rgba(6, 214, 160, 0.3);
}

/* Scanner Options - Enhanced pill button styling */
.scanner-options {
    display: flex;
    justify-content: center;
    margin-bottom: var(--space-lg);
    background: var(--color-bg);
    padding: var(--space-sm);
    border-radius: var(--radius-full);
    box-shadow: inset 0 1px 3px var(--color-shadow);
}

.scanner-option-btn {
    padding: var(--space-sm) var(--space-xl);
    background: transparent;
    border: none;
    cursor: pointer;
    font-size: 0.95rem;
    font-weight: 600;
    margin: 0 var(--space-xs);
    border-radius: var(--radius-full);
    transition: all var(--transition-fast);
    color: var(--color-text-secondary);
    position: relative;
}

.scanner-option-btn.active {
    background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-primary-dark) 100%);
    color: white;
    box-shadow: 0 4px 12px rgba(67, 97, 238, 0.3);
}

.scanner-option-btn:hover:not(.active) {
    color: var(--color-primary);
    background: rgba(67, 97, 238, 0.05);
}

.scanner-method {
    display: none;
    margin-bottom: var(--space-xl);
    animation: fadeIn var(--transition-normal);
}

.scanner-method.active {
    display: block;
}

/* QR Scanner - Camera - Enhanced with better border and effects */
.scanner-container {
    position: relative;
    max-width: 500px;
    margin: 0 auto;
    overflow: hidden;
    border-radius: var(--radius-lg);
    box-shadow: 0 10px 30px var(--color-shadow-heavy);
    border: 4px solid var(--color-bg-card);
}

#scanner-video {
    width: 100%;
    border-radius: var(--radius-md);
    transform: scaleX(-1); /* Mirror video for more natural interaction */
}

.scanner-overlay {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    display: flex;
    align-items: center;
    justify-content: center;
    pointer-events: none;
}

.scanner-frame {
    width: 70%;
    height: 70%;
    border: 2px solid var(--color-primary);
    border-radius: var(--radius-md);
    box-shadow: 0 0 0 9999px var(--color-overlay);
    animation: pulse 2s infinite;
}

@keyframes pulse {
    0% {
        box-shadow: 0 0 0 9999px var(--color-overlay), 0 0 0 0 rgba(67, 97, 238, 0.7);
    }
    70% {
        box-shadow: 0 0 0 9999px var(--color-overlay), 0 0 0 20px rgba(67, 97, 238, 0);
    }
    100% {
        box-shadow: 0 0 0 9999px var(--color-overlay), 0 0 0 0 rgba(67, 97, 238, 0);
    }
}

/* QR Scanner - File Upload & Paste - Enhanced with better styling */
.file-container {
    border: 2px dashed var(--color-primary);
    border-radius: var(--radius-lg);
    padding: var(--space-xl) var(--space-lg);
    text-align: center;
    background-color: var(--color-bg);
    background-image: radial-gradient(circle at 50% 0%, rgba(67, 97, 238, 0.03) 0%, transparent 75%);
    max-width: 500px;
    margin: 0 auto;
    transition: all var(--transition-normal);
    min-height: 250px;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    outline: none;
    box-shadow: 0 5px 15px var(--color-shadow);
}

.file-container:focus, .file-container.drag-over {
    background-color: rgba(67, 97, 238, 0.05);
    border-color: var(--color-primary-dark);
    box-shadow: 0 0 0 4px rgba(67, 97, 238, 0.15), 0 5px 15px var(--color-shadow);
}

.file-content {
    display: flex;
    flex-direction: column;
    align-items: center;
    width: 100%;
}

.file-icons {
    display: flex;
    justify-content: center;
    margin-bottom: var(--space-lg);
    width: 100%;
}

.file-icon {
    margin: 0 var(--space-xl);
    color: var(--color-primary);
    display: flex;
    flex-direction: column;
    align-items: center;
    transition: transform var(--transition-normal);
}

.file-icon:hover {
    transform: translateY(-8px);
    color: var(--color-accent);
}

.file-icon svg {
    filter: drop-shadow(0 4px 6px rgba(67, 97, 238, 0.2));
}

.file-icon p {
    margin-top: var(--space-sm);
    font-size: 0.95rem;
    font-weight: 500;
    color: var(--color-text-secondary);
}

.file-instruction {
    margin: var(--space-lg) 0;
    font-size: 1.05rem;
    color: var(--color-text-secondary);
    background: rgba(67, 97, 238, 0.05);
    padding: var(--space-sm) var(--space-md);
    border-radius: var(--radius-full);
    display: inline-block;
}

#select-file-btn {
    padding: var(--space-sm) var(--space-xl);
    background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-primary-dark) 100%);
    color: white;
    border: none;
    border-radius: var(--radius-full);
    cursor: pointer;
    font-size: 0.95rem;
    font-weight: 500;
    margin-top: var(--space-md);
    transition: all var(--transition-fast);
    box-shadow: 0 4px 10px rgba(67, 97, 238, 0.2);
}

#select-file-btn:hover {
    background: linear-gradient(135deg, var(--color-primary-light) 0%, var(--color-primary) 100%);
    transform: translateY(-2px);
    box-shadow: 0 6px 15px rgba(67, 97, 238, 0.3);
}

#select-file-btn:active {
    transform: translateY(0);
    box-shadow: 0 2px 6px rgba(67, 97, 238, 0.2);
}

/* Result container - Enhanced with better styling */
.result-container {
    margin-top: var(--space-xl);
    text-align: center;
}

.result-container h3 {
    font-size: 1.2rem;
    margin-bottom: var(--space-sm);
    color: var(--color-text);
    font-weight: 600;
}

#scan-result {
    padding: var(--space-md);
    background: var(--color-bg);
    border: 1px solid var(--color-border);
    border-radius: var(--radius-md);
    min-height: 60px;
    margin-top: var(--space-sm);
    word-break: break-all;
    font-family: var(--font-primary);
    transition: all var(--transition-normal);
    box-shadow: inset 0 1px 3px var(--color-shadow);
}

#scan-result:not(:empty) {
    border-color: var(--color-primary);
    background: rgba(67, 97, 238, 0.05);
    box-shadow: 0 0 0 3px rgba(67, 97, 238, 0.1);
}

/* Footer - Enhanced with better styling */
footer {
    margin-top: var(--space-xxl);
    padding-top: var(--space-lg);
    border-top: 1px solid var(--color-border);
    text-align: center;
    color: var(--color-text-secondary);
    font-size: 0.9rem;
}

/* Animation classes */
.pulse-animation {
    animation: pulse-button 0.5s ease;
}

@keyframes pulse-button {
    0% { transform: scale(1); }
    50% { transform: scale(1.05); }
    100% { transform: scale(1); }
}

.pop-animation {
    animation: pop 0.5s ease;
}

@keyframes pop {
    0% { transform: scale(0.8); opacity: 0; }
    50% { transform: scale(1.1); }
    100% { transform: scale(1); opacity: 1; }
}

.download-animation {
    animation: download 0.8s ease;
}

@keyframes download {
    0% { transform: translateY(0); }
    20% { transform: translateY(-5px); }
    40% { transform: translateY(0); }
    100% { transform: translateY(0); }
}

/* Loading animation for QR generation */
.loading-animation {
    position: relative;
    overflow: hidden;
}

.loading-animation::after {
    content: '';
    position: absolute;
    top: 0;
    left: -100%;
    width: 50%;
    height: 100%;
    background: linear-gradient(
        90deg,
        transparent,
        rgba(255, 255, 255, 0.2),
        transparent
    );
    animation: loading-shimmer 1.5s infinite;
}

@keyframes loading-shimmer {
    100% { left: 100%; }
}

/* Toast notifications */
.toast {
    position: fixed;
    bottom: 20px;
    left: 50%;
    transform: translateX(-50%) translateY(100px);
    background: var(--color-bg-card);
    color: var(--color-text);
    padding: 12px 20px;
    border-radius: var(--radius-md);
    box-shadow: 0 4px 12px var(--color-shadow-heavy);
    font-size: 0.9rem;
    z-index: 1000;
    opacity: 0;
    transition: transform 0.3s ease, opacity 0.3s ease;
    min-width: 200px;
    max-width: 90%;
    text-align: center;
    border-left: 4px solid var(--color-primary);
}

.toast.show {
    transform: translateX(-50%) translateY(0);
    opacity: 1;
}

.toast-success {
    border-color: var(--color-success);
}

.toast-error {
    border-color: var(--color-error);
}

.toast-info {
    border-color: var(--color-primary);
}

/* Scan line animation fixes */
#file-canvas:not([hidden]) {
    display: block;
    margin: 20px auto;
    max-width: 100%;
    border-radius: var(--radius-md);
    box-shadow: 0 4px 15px var(--color-shadow);
}

/* Responsive adjustments */
@media (max-width: 768px) {
    :root {
        --space-lg: 1rem;
        --space-xl: 1.5rem;
    }

    .container {
        padding: var(--space-md);
    }

    header {
        flex-direction: column;
        gap: var(--space-md);
    }

    h1 {
        font-size: 2rem;
    }

    .tabs {
        flex-wrap: wrap;
    }

    .tab-btn {
        flex-grow: 1;
        font-size: 0.9rem;
        padding: var(--space-sm) var(--space-md);
    }

    .tab-pane {
        padding: var(--space-lg);
    }

    .input-group {
        flex-direction: column;
    }

    #qr-text {
        border-radius: var(--radius-md);
        margin-bottom: var(--space-md);
        width: 100%;
    }

    #generate-btn {
        border-radius: var(--radius-md);
        width: 100%;
    }

    .scanner-options {
        flex-wrap: wrap;
    }

    .scanner-option-btn {
        margin: var(--space-xs);
        flex: 1;
    }

    .file-icons {
        flex-direction: column;
        gap: var(--space-lg);
    }

    .file-icon {
        margin: 0;
    }

    #qr-canvas {
        max-width: 90%;
    }
}

@media (max-width: 480px) {
    h1 {
        font-size: 1.75rem;
    }

    .file-instruction {
        font-size: 0.9rem;
    }
}

function applyErrorCorrection(data, level) {
  const eccSize = {
    L: 0.1, // Low
    M: 0.15, // Medium
    Q: 0.2, // Quartile
    H: 0.25  // High
  }[level] || 0.15;

  const eccBits = Math.floor(data.length * eccSize);
  const padded = data.concat(new Array(eccBits).fill(0)); // simulate redundancy
  return padded;
}

/**
 * QR Code Error Correction
 * Implements Reed-Solomon error correction coding for QR codes
 */

// Pre-computed Galois field tables for GF(256)
const GF256 = {
  // Exp table: exp[i] = α^i
  exp: [
    1, 2, 4, 8, 16, 32, 64, 128, 29, 58, 116, 232, 205, 135, 19, 38, 
    76, 152, 45, 90, 180, 117, 234, 201, 143, 3, 6, 12, 24, 48, 96, 192, 
    157, 39, 78, 156, 37, 74, 148, 53, 106, 212, 181, 119, 238, 193, 159, 35, 


function gfAdd(a, b) {
  return a ^ b;
}

/**
 * Multiply in GF(256) using pre-computed log/exp tables
 */
function gfMultiply(a, b) {
  if (a === 0 || b === 0) return 0;
  return GF256.exp[(GF256.log[a] + GF256.log[b]) % 255];
}

/**
 * Get generator polynomial for Reed-Solomon encoding
 * @param {number} errorCorrectionLength - Number of error correction codewords
 * @returns {Array} - Generator polynomial coefficients
 */
function getGeneratorPolynomial(errorCorrectionLength) {
  let polynomial = [1]; // Start with g(x) = 1

  // Create the generator polynomial: (x-α^0)(x-α^1)...(x-α^{n-1})
  for (let i = 0; i < errorCorrectionLength; i++) {
    // Multiply by (x-α^i)
    const multiplier = [1, GF256.exp[i]]; // This represents (x-α^i)

    // Result will have one higher degree
    const result = new Array(polynomial.length + 1).fill(0);

    // Multiply polynomials
    for (let j = 0; j < polynomial.length; j++) {
      for (let k = 0; k < multiplier.length; k++) {
        result[j + k] = gfAdd(result[j + k], gfMultiply(polynomial[j], multiplier[k]));
      }
    }

    polynomial = result;
  }

  return polynomial;
}

/**
 * Generate Reed-Solomon error correction codewords
 * @param {Array} dataCodewords - Array of data codewords (bytes)
 * @param {number} eccLength - Number of error correction codewords to generate
 * @returns {Array} - Error correction codewords
 */
function generateECC(dataCodewords, eccLength) {
  // Get the generator polynomial
  const generator = getGeneratorPolynomial(eccLength);

  // Create the dividend polynomial
  const dividend = [...dataCodewords];
  for (let i = 0; i < eccLength; i++) {
    dividend.push(0); // Append zeros to make room for remainder
  }

  // Perform polynomial division
  for (let i = 0; i < dataCodewords.length; i++) {
    const coefficient = dividend[i];
    if (coefficient !== 0) {
      for (let j = 0; j < generator.length; j++) {
        const term = gfMultiply(generator[j], coefficient);
        dividend[i + j] = gfAdd(dividend[i + j], term);
      }
    }
  }

  // Return the remainder (last eccLength bytes)
  return dividend.slice(dataCodewords.length);
}

/**
 * Apply error correction to the data bits for QR code
 * @param {Array} dataBits - Array of data bits
 * @param {string} level - Error correction level (L, M, Q, H)
 * @returns {Array} - Combined data and ECC bits
 */
function applyErrorCorrection(dataBits, level = 'M') {
  // Convert bits to bytes
  const dataBytes = [];
  for (let i = 0; i < dataBits.length; i += 8) {
    let byte = 0;
    for (let j = 0; j < 8; j++) {
      if (i + j < dataBits.length) {
        byte = (byte << 1) | dataBits[i + j];
      }
    }
    dataBytes.push(byte);
  }

  // For version 1-M, we have:
  // - 16 data codewords
  // - 10 error correction codewords
  const eccCount = 10;

  // Generate error correction codewords
  const eccBytes = generateECC(dataBytes, eccCount);

  // Convert all bytes back to bits
  const allBytes = [...dataBytes, ...eccBytes];
  const allBits = [];

  for (const byte of allBytes) {
    for (let i = 7; i >= 0; i--) {
      allBits.push((byte >> i) & 1);
    }
  }

  return allBits;
}

window.addEventListener("DOMContentLoaded", function () {
  const canvas = document.getElementById("qr-canvas-generator");
  const ctx = canvas.getContext("2d");
  const generateBtn = document.getElementById("generate");
  const clearBtn = document.getElementById("clear");
  const downloadBtn = document.getElementById("download");
  const successMsg = document.getElementById("success-msg");

  generateBtn.addEventListener("click", () => {
    const text = document.getElementById("qr-text").value.trim();
    if (!text) {
      alert("Please enter some text to generate QR code.");
      return;
    }

    const binary = textToBinary(text);
    const size = 21; // QR Code version 1 (21x21)
    const modules = Array(size).fill(null).map(() => Array(size).fill(null));

    placeFinderPatterns(modules);
    placeDataBits(modules, binary);

    const scale = 8;
    canvas.width = canvas.height = size * scale;
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    for (let y = 0; y < size; y++) {
      for (let x = 0; x < size; x++) {
        ctx.fillStyle = modules[y][x] ? "#000" : "#fff";
        ctx.fillRect(x * scale, y * scale, scale, scale);
      }
    }

    downloadBtn.style.display = "inline-block";
    successMsg.textContent = "QR code generated successfully!";
  });

  clearBtn.addEventListener("click", () => {
    document.getElementById("qr-text").value = "";
    document.getElementById("filename").value = "";
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    downloadBtn.style.display = "none";
    successMsg.textContent = "";
  });

  downloadBtn.addEventListener("click", () => {
    const filename = document.getElementById("filename").value.trim() || "qr_code";
    const link = document.createElement("a");
    link.download = filename + ".png";
    link.href = canvas.toDataURL("image/png");
    link.click();
  });

  function placeFinderPatterns(matrix) {
    const positions = [
      [0, 0],
      [0, matrix.length - 7],
      [matrix.length - 7, 0],
    ];

    for (const [row, col] of positions) {
      for (let y = 0; y < 7; y++) {
        for (let x = 0; x < 7; x++) {
          const isBorder = x === 0 || y === 0 || x === 6 || y === 6;
          const isCenter = x >= 2 && x <= 4 && y >= 2 && y <= 4;
          matrix[row + y][col + x] = isBorder || isCenter ? 1 : 0;
        }
      }
    }
  }

  function placeDataBits(matrix, dataBits) {
    let col = matrix.length - 1;
    let bitIndex = 0;
    let upward = true;

    while (col > 0) {
      if (col === 6) col--; // Skip timing pattern column

      for (let rowOffset = 0; rowOffset < matrix.length; rowOffset++) {
        const row = upward ? matrix.length - 1 - rowOffset : rowOffset;

        for (let i = 0; i < 2; i++) {
          const c = col - i;
          if (matrix[row][c] === null) {
            matrix[row][c] = dataBits[bitIndex++] || 0;
          }
        }
      }

      col -= 2;
      upward = !upward;
    }
  }
});

/**
 * QR Code Generator
 * Implements QR code matrix creation and rendering
 */

window.addEventListener("DOMContentLoaded", function () {
  const canvas = document.getElementById("qr-canvas-generator");
  const ctx = canvas.getContext("2d");
  const generateBtn = document.getElementById("generate");
  const clearBtn = document.getElementById("clear");
  const downloadBtn = document.getElementById("download");
  const successMsg = document.getElementById("success-msg");

  // Format information bits for each mask pattern (0-7) at Error Correction level M
  // These values are pre-calculated including BCH error correction and mask XOR
  const FORMAT_INFO_M = [
    0x77C4, 0x72F3, 0x7DAA, 0x789D, 0x662F, 0x6318, 0x6C41, 0x6976
  ];

  generateBtn.addEventListener("click", () => {
    const text = document.getElementById("qr-text").value.trim();
    if (!text) {
      alert("Please enter some text to generate QR code.");
      return;
    }

    // Start QR code generation
    generateQRCode(text);
  });

  clearBtn.addEventListener("click", () => {
    document.getElementById("qr-text").value = "";
    document.getElementById("filename").value = "";
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    downloadBtn.style.display = "none";
    successMsg.textContent = "";
  });

  downloadBtn.addEventListener("click", () => {
    const filename = document.getElementById("filename").value.trim() || "qr_code";
    const link = document.createElement("a");
    link.download = filename + ".png";
    link.href = canvas.toDataURL("image/png");
    link.click();
  });

  /**
   * Main function to generate QR code
   * @param {string} text - Text to encode in the QR code
   */
  function generateQRCode(text) {
    // 1. Convert text to binary data with proper QR encoding
    const dataBits = textToBinary(text);

    // 2. Add error correction codewords
    const finalBits = applyErrorCorrection(dataBits, 'M');

    // 3. Create the QR matrix (21x21 for version 1)
    const size = 21;
    const matrix = Array(size).fill().map(() => Array(size).fill(null));

    // 4. Add function patterns (finder patterns, timing patterns, etc.)
    addFunctionPatterns(matrix);

    // 5. Place data bits in the matrix
    placeData(matrix, finalBits);

    // 6. Find the best mask pattern
    const bestMask = findBestMask(matrix);

    // 7. Apply mask and add format information
    const finalMatrix = applyMaskAndFormat(matrix, bestMask);

    // 8. Render the QR code
    renderQRCode(finalMatrix);
  }

  /**
   * Add function patterns to QR matrix
   * @param {Array} matrix - QR code matrix
   */
  function addFunctionPatterns(matrix) {
    const size = matrix.length;

    // Add finder patterns (top-left, top-right, bottom-left)
    addFinderPattern(matrix, 0, 0);
    addFinderPattern(matrix, 0, size - 7);
    addFinderPattern(matrix, size - 7, 0);

    // Add separator zones around finder patterns
    addSeparators(matrix);

    // Add timing patterns
    for (let i = 8; i < size - 8; i++) {
      matrix[6][i] = i % 2 === 0 ? 1 : 0; // Horizontal timing pattern
      matrix[i][6] = i % 2 === 0 ? 1 : 0; // Vertical timing pattern
    }

    // Add dark module
    matrix[size - 8][8] = 1;
  }

  /**
   * Add a finder pattern at the specified position
   * @param {Array} matrix - QR code matrix
   * @param {number} row - Starting row
   * @param {number} col - Starting column
   */
  function addFinderPattern(matrix, row, col) {
    // 7x7 finder pattern
    for (let r = 0; r < 7; r++) {
      for (let c = 0; c < 7; c++) {
        // Outer border is black (1)
        // Inner 3x3 square is black (1)
        // The remaining area is white (0)
        const isBorder = r === 0 || r === 6 || c === 0 || c === 6;
        const isInner = r >= 2 && r <= 4 && c >= 2 && c <= 4;
        matrix[row + r][col + c] = isBorder || isInner ? 1 : 0;
      }
    }
  }

  /**
   * Add white separator zones around finder patterns
   * @param {Array} matrix - QR code matrix
   */
  function addSeparators(matrix) {
    const size = matrix.length;

    // Top-left finder pattern
    for (let r = 0; r < 8; r++) {
      if (r === 7) {
        for (let c = 0; c < 8; c++) {
          matrix[r][c] = 0;
        }
      }
      if (r < 7) matrix[r][7] = 0;
    }

    // Top-right finder pattern
    for (let r = 0; r < 8; r++) {
      if (r === 7) {
        for (let c = size - 8; c < size; c++) {
          matrix[r][c] = 0;
        }
      }
      if (r < 7) matrix[r][size - 8] = 0;
    }

    // Bottom-left finder pattern
    for (let c = 0; c < 8; c++) {
      if (c === 7) {
        for (let r = size - 8; r < size; r++) {
          matrix[r][c] = 0;
        }
      }
      if (c < 7) matrix[size - 8][c] = 0;
    }
  }

  /**
   * Place data bits in the QR matrix
   * @param {Array} matrix - QR code matrix
   * @param {Array} bits - Data bits to place
   */
  function placeData(matrix, bits) {
    const size = matrix.length;
    let bitIndex = 0;
    let upward = true;

    // Start from bottom right, moving in a zigzag pattern
    for (let right = size - 1; right >= 1; right -= 2) {
      // Skip the vertical timing pattern
      if (right === 6) right = 5;

      // Direction alternates between upward and downward
      const rowSequence = upward 
        ? Array.from({length: size}, (_, i) => size - 1 - i) // Bottom to top
        : Array.from({length: size}, (_, i) => i);            // Top to bottom

      for (const row of rowSequence) {
        for (let col = right; col > right - 2 && col >= 0; col--) {
          // Skip if cell is already filled with function pattern
          if (matrix[row][col] === null) {
            // Place a bit if available, otherwise use 0
            matrix[row][col] = bitIndex < bits.length ? bits[bitIndex++] : 0;
          }
        }
      }

      // Switch direction for next column pair
      upward = !upward;
    }
  }

  /**

/**
 * IntelliQR App
 * Main application script for QR code generation and scanning
 */

document.addEventListener('DOMContentLoaded', () => {
    // Initialize the application
    const app = new IntelliQRApp();
    app.init();
});

class IntelliQRApp {
    constructor() {
        // DOM elements
        this.tabs = document.querySelectorAll('.tab-btn');
        this.tabContents = document.querySelectorAll('.tab-pane');

        // Generator elements
        this.qrText = document.getElementById('qr-text');
        this.generateBtn = document.getElementById('generate-btn');
        this.qrCanvas = document.getElementById('qr-canvas');
        this.downloadBtn = document.getElementById('download-btn');

        // Scanner elements
        this.scannerVideo = document.getElementById('scanner-video');
        this.scanResult = document.getElementById('scan-result');

        // Scanner option buttons
        this.scannerOptionBtns = document.querySelectorAll('.scanner-option-btn');
        this.cameraBtn = document.getElementById('camera-btn');
        this.fileBtn = document.getElementById('file-btn');

        // Scanner method containers
        this.scannerMethods = document.querySelectorAll('.scanner-method');
        this.cameraScanner = document.getElementById('camera-scanner');
        this.fileScanner = document.getElementById('file-scanner');

        // File upload & paste elements
        this.dropArea = document.getElementById('drop-area');
        this.fileInput = document.getElementById('file-input');
        this.selectFileBtn = document.getElementById('select-file-btn');
        this.fileCanvas = document.getElementById('file-canvas');

        // Theme toggle
        this.themeToggle = document.getElementById('theme-toggle');

        // Set canvas dimensions
        this.qrCanvas.width = 256;
        this.qrCanvas.height = 256;
        this.fileCanvas.width = 500;
        this.fileCanvas.height = 500;

        // Create QR generator instance
        this.qrGenerator = window.QRCodeGenerator.create({
            correctLevel: "H", // Highest error correction for better scanning
        });

        // Scanner state
        this.scanner = {
            active: false,
            stream: null,
            canvasElement: document.createElement('canvas'),
            canvasContext: null,
            requestId: null
        };

        this.scanner.canvasContext = this.scanner.canvasElement.getContext('2d', { willReadFrequently: true });

        // Initialize theme based on user preference
        this.initTheme();
    }

    /**
     * Initialize the application
     */
    init() {
        // Set up event listeners
        this.setupEventListeners();

        // Apply animations to elements
        this.applyAnimations();
    }

    /**
     * Initialize theme based on user preferences
     */
    initTheme() {
        // Check for saved theme preference or use system preference
        const savedTheme = localStorage.getItem('theme');

        if (savedTheme) {
            document.documentElement.dataset.theme = savedTheme;
        } else {
            // Check if user prefers dark mode
            const prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
            if (prefersDark) {
                document.documentElement.dataset.theme = 'dark';
            }
        }
    }

    /**
     * Toggle between light and dark themes
     */
    toggleTheme() {
        const currentTheme = document.documentElement.dataset.theme;
        const newTheme = currentTheme === 'dark' ? 'light' : 'dark';

        // Apply animation for smooth transition
        document.documentElement.classList.add('theme-transition');

        // Set new theme
        document.documentElement.dataset.theme = newTheme;

        // Store theme preference
        localStorage.setItem('theme', newTheme);

        // Remove transition class after animation completes
        setTimeout(() => {
            document.documentElement.classList.remove('theme-transition');
        }, 300);
    }

    /**
     * Apply animations to key elements for better UX
     */
    applyAnimations() {
        // Animate title on load
        const title = document.querySelector('h1');
        title.style.opacity = '0';
        title.style.transform = 'translateY(-20px)';

        setTimeout(() => {
            title.style.transition = 'opacity 0.5s ease, transform 0.5s ease';
            title.style.opacity = '1';
            title.style.transform = 'translateY(0)';
        }, 100);

        // Stagger tab button animations
        this.tabs.forEach((tab, index) => {
            tab.style.opacity = '0';
            tab.style.transform = 'translateY(-10px)';

            setTimeout(() => {
                tab.style.transition = 'opacity 0.3s ease, transform 0.3s ease, background 0.2s ease, color 0.2s ease';
                tab.style.opacity = '1';
                tab.style.transform = 'translateY(0)';
            }, 200 + index * 100);
        });
    }

    /**
     * Set up event listeners
     */
    setupEventListeners() {
        // Tab switching
        this.tabs.forEach(tab => {
            tab.addEventListener('click', () => this.switchTab(tab.dataset.tab));
        });

        // QR code generation
        this.generateBtn.addEventListener('click', () => this.generateQRCode());
        this.qrText.addEventListener('keypress', (e) => {
            if (e.key === 'Enter') {
                this.generateQRCode();
            }
        });

        // Download QR code
        this.downloadBtn.addEventListener('click', () => this.downloadQRCode());

        // Theme toggle
        this.themeToggle.addEventListener('click', () => this.toggleTheme());

        // Scanner method switching
        this.scannerOptionBtns.forEach(btn => {
            btn.addEventListener('click', () => {
                const methodId = btn.id.split('-')[0]; // Extract 'camera' or 'file' from button id
                this.switchScannerMethod(methodId);
            });
        });

        // File upload handlers
        this.selectFileBtn.addEventListener('click', () => this.fileInput.click());
        this.fileInput.addEventListener('change', () => {
            if (this.fileInput.files.length > 0) {
                this.handleFileSelect(this.fileInput.files[0]);
            }
        });

        // Drag and drop handlers
        this.dropArea.addEventListener('dragover', (e) => this.handleDragOver(e));
        this.dropArea.addEventListener('dragleave', (e) => this.handleDragLeave(e));
        this.dropArea.addEventListener('drop', (e) => this.handleDrop(e));

        // Paste handler - make the entire drop area focusable
        this.dropArea.addEventListener('click', () => this.dropArea.focus());
        this.dropArea.addEventListener('paste', (e) => this.handlePaste(e));

        // Global paste event listener
        document.addEventListener('paste', (e) => {
            // Only process paste if we're on the file scanner method
            if (this.fileScanner.classList.contains('active')) {
                this.handlePaste(e);
            }
        });
    }

    /**
     * Switch between tabs
     */
    switchTab(tabId) {
        // Update active tab button
        this.tabs.forEach(tab => {
            tab.classList.toggle('active', tab.dataset.tab === tabId);
        });

        // Get the old and new tab content elements
        const oldTabContent = document.querySelector('.tab-pane.active');
        const newTabContent = document.getElementById(tabId);

        // Apply exit animation to old tab
        if (oldTabContent) {
            oldTabContent.classList.add('tab-exit');
            setTimeout(() => {
                oldTabContent.classList.remove('active');
                oldTabContent.classList.remove('tab-exit');

                // Apply entrance animation to new tab
                newTabContent.classList.add('active');

                // Start scanner if switching to scanner tab and camera method is active
                if (tabId === 'scanner' && this.cameraScanner.classList.contains('active') && !this.scanner.active) {
                    this.startScanner();
                }
            }, 300);
        }

        // Stop scanner if switching away from scanner tab
        if (oldTabContent && oldTabContent.id === 'scanner' && this.scanner.active) {
            this.stopScanner();
        }
    }

    /**
     * Switch between scanner methods (camera or file)
     */
    switchScannerMethod(methodId) {
        // Update active button with animation
        this.scannerOptionBtns.forEach(btn => {
            const isActive = btn.id === `${methodId}-btn`;
            if (isActive && !btn.classList.contains('active')) {
                btn.classList.add('pulse-animation');
                setTimeout(() => {
                    btn.classList.remove('pulse-animation');
                }, 500);
            }
            btn.classList.toggle('active', isActive);
        });

        // Get current active method and new method
        const currentMethod = document.querySelector('.scanner-method.active');
        const newMethod = document.getElementById(`${methodId}-scanner`);

        // Don't proceed if the same method is already active
        if (currentMethod === newMethod) return;

        // Apply transition
        if (currentMethod) {
            currentMethod.classList.add('fade-out');

            setTimeout(() => {
                currentMethod.classList.remove('active');
                currentMethod.classList.remove('fade-out');

                newMethod.classList.add('active');
                newMethod.classList.add('fade-in');

                setTimeout(() => {
                    newMethod.classList.remove('fade-in');
                }, 300);

                // Start or stop camera as needed
                if (methodId === 'camera' && !this.scanner.active) {
                    this.startScanner();
                } else if (methodId !== 'camera' && this.scanner.active) {
                    this.stopScanner();
                }
            }, 300);
        }

        // Reset result
        this.scanResult.textContent = 'No QR code detected';
    }

    /**
     * Generate QR code from input text
     */
    generateQRCode() {
        const text = this.qrText.value.trim();

        if (!text) {
            this.showToast('Please enter text or URL to generate QR code', 'error');
            this.qrText.focus();
            return;
        }

        try {
            // Show loading animation
            this.qrCanvas.classList.add('loading-animation');

            // Generate QR code and render to canvas after a slight delay to show loading
            setTimeout(() => {
                this.qrGenerator.generate(text, 'qr-canvas');
                this.qrCanvas.classList.remove('loading-animation');

                // Show download button with animation
                this.downloadBtn.style.display = 'block';
                this.downloadBtn.classList.add('pop-animation');

                setTimeout(() => {
                    this.downloadBtn.classList.remove('pop-animation');
                }, 500);

                this.showToast('QR Code generated successfully', 'success');
            }, 600);
        } catch (error) {
            console.error('Error generating QR code:', error);
            this.showToast('Failed to generate QR code. Please try again.', 'error');
            this.qrCanvas.classList.remove('loading-animation');
        }
    }

    /**
     * Show toast notification
     */
    showToast(message, type = 'info') {
        // Remove existing toast
        const existingToast = document.querySelector('.toast');
        if (existingToast) {
            existingToast.remove();
        }

        // Create new toast
        const toast = document.createElement('div');
        toast.className = `toast toast-${type}`;
        toast.textContent = message;

        // Add to body
        document.body.appendChild(toast);

        // Show toast
        setTimeout(() => {
            toast.classList.add('show');
        }, 10);

        // Hide toast after delay
        setTimeout(() => {
            toast.classList.remove('show');
            setTimeout(() => {
                toast.remove();
            }, 300);
        }, 3000);
    }

    /**
     * Download the generated QR code as PNG
     */
    downloadQRCode() {
        const link = document.createElement('a');
        link.download = 'qrcode.png';
        link.href = this.qrCanvas.toDataURL('image/png');

        // Add download animation
        this.downloadBtn.classList.add('download-animation');
        setTimeout(() => {
            link.click();
            setTimeout(() => {
                this.downloadBtn.classList.remove('download-animation');
            }, 500);
        }, 300);
    }

    /**
     * Handle drag over event for file drop area
     */
    handleDragOver(e) {
        e.preventDefault();
        e.stopPropagation();
        this.dropArea.classList.add('drag-over');
    }

    /**
     * Handle drag leave event for file drop area
     */
    handleDragLeave(e) {
        e.preventDefault();
        e.stopPropagation();
        this.dropArea.classList.remove('drag-over');
    }

    /**
     * Handle file drop event
     */
    handleDrop(e) {
        e.preventDefault();
        e.stopPropagation();
        this.dropArea.classList.remove('drag-over');

        // Get the dropped file
        const file = e.dataTransfer.files[0];
        if (file) {
            this.handleFileSelect(file);
        }
    }

    /**
     * Handle file selection from input or drop
     */
    handleFileSelect(file) {
        if (!file || !file.type.startsWith('image/')) {
            this.showToast('Please select an image file', 'error');
            return;
        }

        // Show loading state
        this.showToast('Processing image...', 'info');

        const reader = new FileReader();
        reader.onload = (e) => {
            const img = new Image();
            img.onload = () => this.processImageForQR(img, this.fileCanvas);
            img.onerror = () => this.showToast('Error loading image', 'error');
            img.src = e.target.result;
        };
        reader.onerror = () => this.showToast('Error reading file', 'error');
        reader.readAsDataURL(file);
    }

    /**
     * Handle paste event for clipboard images
     */
    handlePaste(e) {
        const items = (e.clipboardData || window.clipboardData).items;

        let imageItem = null;
        for (let i = 0; i < items.length; i++) {
            if (items[i].type.indexOf('image') !== -1) {
                imageItem = items[i];
                break;
            }
        }

        if (imageItem) {
            // Show loading animation
            this.showToast('Processing pasted image...', 'info');

            const blob = imageItem.getAsFile();
            const reader = new FileReader();
            reader.onload = (e) => {
                const img = new Image();
                img.onload = () => this.processImageForQR(img, this.fileCanvas);
                img.src = e.target.result;
            };
            reader.readAsDataURL(blob);
        } else {
            this.showToast('No image found in clipboard', 'error');
        }
    }

    /**
     * Process an image to detect QR codes
     */
    processImageForQR(img, canvas) {
        const ctx = canvas.getContext('2d');

        // Calculate dimensions to maintain aspect ratio
        let width = img.width;
        let height = img.height;
        const maxDimension = Math.max(canvas.width, canvas.height);

        if (width > height && width > maxDimension) {
            height = height * (maxDimension / width);
            width = maxDimension;
        } else if (height > maxDimension) {
            width = width * (maxDimension / height);
            height = maxDimension;
        }

        // Clear canvas and draw image
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        canvas.width = width;
        canvas.height = height;

        ctx.drawImage(img, 0, 0, width, height);
        canvas.hidden = false;

        // Add scan line animation
        this.addScanLineAnimation(canvas, img);

        // Get image data for QR detection
        const imageData = ctx.getImageData(0, 0, width, height);

        // Try to detect QR code
        this.detectQRCodeInImage(imageData);
    }

    /**
     * Add scan line animation to canvas
     */
    addScanLineAnimation(canvas, img) {
        const ctx = canvas.getContext('2d');
        const height = canvas.height;
        const width = canvas.width;

        // Store image reference for redrawing later
        this._currentImage = img;

        let y = 0;
        let direction = 1;

        // Clear any existing animation
        if (this._scanLineInterval) {
            clearInterval(this._scanLineInterval);
        }

        this._scanLineInterval = setInterval(() => {
            // Clear previous scan line by redrawing that part of the image
            ctx.clearRect(0, y - 2, width, 4);

            // Draw new scan line
            ctx.beginPath();
            ctx.moveTo(0, y);
            ctx.lineTo(width, y);
            ctx.strokeStyle = 'rgba(58, 109, 240, 0.7)';
            ctx.lineWidth = 2;
            ctx.stroke();

            // Move scan line
            y += direction * 4;

            // Reverse direction at edges
            if (y >= height - 2 || y <= 2) {
                direction *= -1;
            }
        }, 30);

        // Stop animation after 3 seconds
        setTimeout(() => {
            if (this._scanLineInterval) {
                clearInterval(this._scanLineInterval);
                this._scanLineInterval = null;

                // Redraw the image to remove scan line
                ctx.clearRect(0, 0, width, height);
                if (this._currentImage) {
                    ctx.drawImage(this._currentImage, 0, 0, width, height);
                }
            }
        }, 3000);
    }

    /**
     * Detect QR code in an image
     */
    detectQRCodeInImage(imageData) {
        // First try with BarcodeDetector API if available
        if (window.BarcodeDetector) {
            this.detectQRWithBarcodeDetector(imageData)
                .then(result => {
                    if (result) {
                        this.scanResult.textContent = result;
                        this.showToast('QR Code detected!', 'success');
                    } else {
                        // Fallback to jsQR
                        this.detectQRWithJSQR(imageData);
                    }
                })
                .catch(error => {
                    console.error('BarcodeDetector error:', error);
                    this.detectQRWithJSQR(imageData);
                });
        } else {
            // Use jsQR if BarcodeDetector is not available
            this.detectQRWithJSQR(imageData);
        }
    }

    /**
     * Detect QR with jsQR library
     */
    detectQRWithJSQR(imageData) {
        // Load jsQR if not already loaded
        if (!window.jsQR) {
            this.showToast('Loading QR scanner library...', 'info');
            this.loadJSQR(() => this.detectQRWithJSQR(imageData));
            return;
        }

        try {
            const code = window.jsQR(
                imageData.data,
                imageData.width,
                imageData.height,
                { inversionAttempts: 'dontInvert' }
            );

            if (code && code.data) {
                this.scanResult.textContent = code.data;
                this.showToast('QR Code detected!', 'success');
            } else {
                this.scanResult.textContent = 'No QR code found in image';
                this.showToast('No QR code found', 'error');
            }
        } catch (error) {
            console.error('jsQR detection error:', error);
            this.scanResult.textContent = 'Error processing image';
            this.showToast('Error processing image', 'error');
        }
    }

    /**
     * Start the QR code scanner
     */
    async startScanner() {
        try {
            // Show loading state
            this.showToast('Accessing camera...', 'info');

            // Request camera access
            const constraints = {
                video: {
                    facingMode: 'environment',
                    width: { ideal: 1280 },
                    height: { ideal: 720 }
                }
            };

            this.scanner.stream = await navigator.mediaDevices.getUserMedia(constraints);
            this.scannerVideo.srcObject = this.scanner.stream;

            // Wait for video to load
            await new Promise(resolve => {
                this.scannerVideo.onloadedmetadata = () => {
                    this.scannerVideo.play();
                    resolve();
                };
            });

            // Set canvas size to match video
            this.scanner.canvasElement.width = this.scannerVideo.videoWidth;
            this.scanner.canvasElement.height = this.scannerVideo.videoHeight;

            // Start scanning
            this.scanner.active = true;
            this.scanFrames();

            // Update UI
            this.scanResult.textContent = 'Scanning...';
            this.showToast('Camera ready! Scanning for QR codes...', 'success');
        } catch (error) {
            console.error('Error accessing camera:', error);
            this.scanResult.textContent = 'Error accessing camera. Please check permissions.';
            this.showToast('Camera access denied', 'error');
        }
    }

    /**
     * Stop the QR code scanner
     */
    stopScanner() {
        if (this.scanner.stream) {
            // Stop all video tracks
            this.scanner.stream.getTracks().forEach(track => track.stop());
            this.scanner.stream = null;
        }

        // Cancel the animation frame
        if (this.scanner.requestId) {
            cancelAnimationFrame(this.scanner.requestId);
            this.scanner.requestId = null;
        }

        this.scanner.active = false;
    }

    /**
     * Continuously scan video frames for QR codes
     */
    scanFrames() {
        if (!this.scanner.active) return;

        // Process the current video frame
        this.processVideoFrame();

        // Schedule the next frame
        this.scanner.requestId = requestAnimationFrame(() => this.scanFrames());
    }

    /**
     * Process a video frame to detect QR codes
     */
    processVideoFrame() {
        try {
            if (this.scannerVideo.readyState === this.scannerVideo.HAVE_ENOUGH_DATA) {
                // Draw video frame to canvas
                const ctx = this.scanner.canvasContext;
                const canvas = this.scanner.canvasElement;
                ctx.drawImage(this.scannerVideo, 0, 0, canvas.width, canvas.height);

                // Get image data
                const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);

                // Try to detect QR code in the frame
                const qrCode = this.detectQRCode(imageData);

                if (qrCode) {
                    // QR code detected, display result
                    this.scanResult.textContent = qrCode;
                    this.showToast('QR Code detected!', 'success');

                    // Pause scanning briefly after successful detection
                    this.scanner.active = false;
                    setTimeout(() => {
                        if (this.cameraScanner.classList.contains('active')) {
                            this.scanner.active = true;
                            this.scanFrames();
                        }
                    }, 1500);
                }
            }
        } catch (error) {
            console.error('Error processing video frame:', error);
        }
    }

    /**
     * Detect a QR code in the image data (for video frames)
     */
    detectQRCode(imageData) {
        // Try with BarcodeDetector API if available
        if (window.BarcodeDetector) {
            return this.detectQRWithBarcodeDetector(imageData);
        }

        // Otherwise use jsQR
        return this.detectQRManually(imageData);
    }

    /**
     * Detect QR codes using the BarcodeDetector API (if available)
     */
    async detectQRWithBarcodeDetector(imageData) {
        try {
            // Create detector
            const barcodeDetector = new BarcodeDetector({
                formats: ['qr_code']
            });

            // Detect codes
            const barcodes = await barcodeDetector.detect(imageData);

            if (barcodes.length > 0) {
                return barcodes[0].rawValue;
            }
        } catch (error) {
            console.error('BarcodeDetector error:', error);
        }

        return null;
    }

    /**
     * Manual QR code detection using jsQR library
     */
    detectQRManually(imageData) {
        if (!this._qrScanner) {
            // Lazily load jsQR library if it's available
            if (window.jsQR) {
                this._qrScanner = window.jsQR;
            } else {
                // Load jsQR if not already loaded
                this.loadJSQR();
                return null; // Skip this frame while loading
            }
        }

        if (this._qrScanner) {
            const code = this._qrScanner(
                imageData.data,
                imageData.width,
                imageData.height,
                { inversionAttempts: 'dontInvert' }
            );

            if (code && code.data) {
                return code.data;
            }
        }

        return null;
    }

    /**
     * Dynamically load the jsQR library
     */
    loadJSQR(callback) {
        if (this._loadingJSQR) return;
        this._loadingJSQR = true;

        const script = document.createElement('script');
        script.src = 'https://cdn.jsdelivr.net/npm/jsqr@1.4.0/dist/jsQR.min.js';
        script.onload = () => {
            this._qrScanner = window.jsQR;
            this._loadingJSQR = false;
            if (callback && typeof callback === 'function') {
                callback();
            }
        };
        script.onerror = () => {
            console.error('Failed to load jsQR library');
            this._loadingJSQR = false;

            // Show error message
            this.scanResult.textContent = 'QR scanner libraries could not be loaded.';
            this.showToast('Error loading scanner libraries', 'error');
        };

        document.head.appendChild(script);
    }
}

/**
 * IntelliQR - QR Code Library
 * A vanilla JavaScript library for generating QR codes
 */

class QRCode {
    constructor(options = {}) {
        this.options = {
            width: 256,
            height: 256,
            colorDark: "#000000",
            colorLight: "#ffffff",
            correctLevel: "H", // L, M, Q, H
            margin: 4, // QR code margin
            ...options
        };

        // Preload the library on init for faster generation
        this._libraryLoaded = this._loadQRCodeLibrary().catch(err => {
            console.warn("QR code library preload failed:", err);
        });
    }

    /**
     * Load the QRCode.js library dynamically
     */
    async _loadQRCodeLibrary() {
        return new Promise((resolve, reject) => {
            // Check if library is already loaded
            if (window.QRCode) {
                resolve(window.QRCode);
                return;
            }

            // Try to load from CDN
            const script = document.createElement('script');
            script.src = 'https://cdn.jsdelivr.net/npm/qrcode-generator@1.4.4/qrcode.min.js';
            script.onload = () => resolve(window.QRCode);
            script.onerror = () => {
                // Try alternate CDN if first one fails
                const backupScript = document.createElement('script');
                backupScript.src = 'https://cdnjs.cloudflare.com/ajax/libs/qrcode-generator/1.4.4/qrcode.min.js';
                backupScript.onload = () => resolve(window.QRCode);
                backupScript.onerror = () => reject(new Error("Failed to load QR Code library from multiple sources"));
                document.head.appendChild(backupScript);
            };
            document.head.appendChild(script);
        });
    }

    /**
     * Generate a QR code using the library
     */
    async generate(text, elementId) {
        try {
            // Make sure library is loaded
            await this._libraryLoaded;

            if (!window.QRCode) {
                throw new Error("QR code library not available");
            }

            const canvas = document.getElementById(elementId);
            if (!canvas || !(canvas instanceof HTMLCanvasElement)) {
                throw new Error(`Element with ID "${elementId}" is not a valid canvas element`);
            }

            // Map our correction level to the library's
            const correctLevelMap = {
                "L": window.QRCode.Ecc.L,
                "M": window.QRCode.Ecc.M,
                "Q": window.QRCode.Ecc.Q,
                "H": window.QRCode.Ecc.H
            };

            const correctLevel = correctLevelMap[this.options.correctLevel] || window.QRCode.Ecc.H;

            // Calculate optimal type number based on text length
            // 0 means auto-detect
            const typeNumber = 0;

            // Generate QR code
            const qr = window.QRCode(typeNumber, correctLevel);
            qr.addData(text);
            qr.make();

            // Render to canvas with proper scaling
            const ctx = canvas.getContext('2d');
            const moduleCount = qr.getModuleCount();
            const margin = this.options.margin || 4;

            // Calculate scaling for the modules
            const contentSize = canvas.width - (margin * 2);
            const scale = contentSize / moduleCount;

            // Clear canvas
            ctx.fillStyle = this.options.colorLight;
            ctx.fillRect(0, 0, canvas.width, canvas.height);

            // Draw QR code
            ctx.fillStyle = this.options.colorDark;
            for (let row = 0; row < moduleCount; row++) {
                for (let col = 0; col < moduleCount; col++) {
                    if (qr.isDark(row, col)) {
                        ctx.fillRect(
                            Math.round(col * scale) + margin,
                            Math.round(row * scale) + margin,
                            Math.ceil(scale),
                            Math.ceil(scale)
                        );
                    }
                }
            }

            return qr;
        } catch (error) {
            console.error("Error generating QR code:", error);
            // Try one more time with direct library load
            return this._fallbackDirectLibrary(text, elementId);
        }
    }

    /**
     * Ultimate fallback - try using another QR code library
     */
    async _fallbackDirectLibrary(text, elementId) {
        return new Promise((resolve, reject) => {
            // Try loading QRious as a final fallback
            const script = document.createElement('script');
            script.src = 'https://cdnjs.cloudflare.com/ajax/libs/qrious/4.0.2/qrious.min.js';
            script.onload = () => {
                try {
                    const canvas = document.getElementById(elementId);

                    // Create QR code with QRious
                    const qr = new window.QRious({
                        element: canvas,
                        value: text,
                        size: canvas.width,
                        backgroundAlpha: 1,
                        foreground: this.options.colorDark,
                        background: this.options.colorLight,
                        level: this.options.correctLevel.toLowerCase(),
                        padding: this.options.margin
                    });

                    resolve(qr);
                } catch (err) {
                    reject(new Error("All QR generation methods failed"));
                }
            };
            script.onerror = () => reject(new Error("All QR generation methods failed"));
            document.head.appendChild(script);
        });
    }
}

// Export the QRCode class
window.QRCodeGenerator = {
    create: function(options) {
        return new QRCode(options);
    }
};

function textToBinary(text) {
  const modeIndicator = "0100"; // Byte mode
  const charCount = text.length;
  const charCountBin = charCount.toString(2).padStart(8, "0"); // For version 1

  let dataBits = "";
  for (let i = 0; i < charCount; i++) {
    const charCode = text.charCodeAt(i);
    const bin = charCode.toString(2).padStart(8, "0");
    dataBits += bin;
  }

  let bitStream = modeIndicator + charCountBin + dataBits;

  // Add terminator (up to 4 bits)
  const maxBits = 152; // Version 1, Level M = 19 data bytes = 152 bits
  if (bitStream.length < maxBits) {
    bitStream += "0000";
  }

  // Pad to byte boundary
  while (bitStream.length % 8 !== 0) {
    bitStream += "0";
  }

  // Add pad bytes 0b11101100 and 0b00010001 alternately
  const padBytes = ["11101100", "00010001"];
  let i = 0;
  while (bitStream.length < maxBits) {
    bitStream += padBytes[i % 2];
    i++;
  }

  return bitStream.split("").map(b => parseInt(b));
}

/**
 * QR Code Utilities
 * Contains functions for encoding data for QR code generation
 */

// Mode indicators for QR Code
const MODE = {
  NUMERIC: '0001',
  ALPHANUMERIC: '0010',
  BYTE: '0100',
  KANJI: '1000'
};

/**
 * Encode text in Byte mode for QR Code Version 1-M
 * @param {string} text - Text to encode
 * @returns {Array} - Array of bits (0s and 1s)
 */
function textToBinary(text) {
  // For Version 1, character count uses 8 bits
  const charCount = Math.min(text.length, 17); // Max 17 characters for Version 1-M
  const charCountBinary = charCount.toString(2).padStart(8, '0');

  // Mode indicator + Character count + Data
  let bitStream = MODE.BYTE + charCountBinary;

  // Convert each character to 8-bit binary
  for (let i = 0; i < charCount; i++) {
    const charCode = text.charCodeAt(i);
    const binaryChar = charCode.toString(2).padStart(8, '0');
    bitStream += binaryChar;
  }

  // Calculate remaining bits needed to reach the capacity
  // Version 1-M has 16 codewords (128 bits) for data
  const dataCapacity = 128;
  const currentLength = bitStream.length;
  let remainingBits = dataCapacity - currentLength;

  // Add terminator (up to 4 bits if space available)
  const terminatorLength = Math.min(4, remainingBits);
  if (terminatorLength > 0) {
    bitStream += '0'.repeat(terminatorLength);
    remainingBits -= terminatorLength;
  }

  // Pad to byte boundary if needed
  const paddingToByteLength = remainingBits % 8;
  if (paddingToByteLength > 0) {
    bitStream += '0'.repeat(paddingToByteLength);

  // Add pad bytes 0b11101100 and 0b00010001 alternately
  const padBytes = ["11101100", "00010001"];
  let i = 0;
  while (bitStream.length < maxBits) {
    bitStream += padBytes[i % 2];
    i++;
  }

  return bitStream.split("").map(b => parseInt(b));
}

  return bitStream.split('').map(bit => parseInt(bit, 10));
}
